import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
void main(){test('assistant session specified by metadata must be declared and protected',(){final manifest=File('android/app/src/main/AndroidManifest.xml').readAsStringSync();final xml=File('android/app/src/main/res/xml/voice_interaction_service.xml').readAsStringSync();final name=RegExp('android:sessionService="([^"]+)"').firstMatch(xml)!.group(1)!;final service=RegExp('<service\\s[^>]*android:name="${RegExp.escape(name)}"[^>]*>',dotAll:true).firstMatch(manifest);expect(service,isNotNull);expect(service!.group(0),contains('android.permission.BIND_VOICE_INTERACTION'));});}
